SELECT 'batch_011_4131044b_wav_04' AS batch_id,(SELECT COUNT(*) FROM song_masters WHERE id IN ('sm-upload-46552f7f-fae','sm-upload-56571117-ce0','sm-upload-a0ec2a9f-fe9','sm-upload-f3f4157d-6ee') AND album_id='al-3a2710cebd830ec6fee4ae8c4131044b') AS candidate_masters_in_target,(SELECT COUNT(*) FROM song_masters WHERE id IN ('sm-upload-46552f7f-fae','sm-upload-56571117-ce0','sm-upload-a0ec2a9f-fe9','sm-upload-f3f4157d-6ee') AND album_id='pending-uploads') AS candidate_masters_still_pending,(SELECT COUNT(*) FROM albums WHERE id='al-3a2710cebd830ec6fee4ae8c4131044b' AND name='春华秋拾') AS target_album_rows,(SELECT song_count FROM albums WHERE id='al-3a2710cebd830ec6fee4ae8c4131044b') AS stored_song_count,(SELECT COALESCE(SUM(si.size),0) FROM song_instances si JOIN song_masters sm ON sm.id=si.master_id WHERE sm.album_id='al-3a2710cebd830ec6fee4ae8c4131044b') AS calculated_size;
